<!doctype html>
<html lang="ru">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#e8f2f7">
    <meta name="description" content="Научитесь управлять кайтом и кататься на сноуборде по снегу и льду. Поэтапное обучение с инструктором для начинающих.">
    <title>Сноукайтинг — почувствуй ветер, освой снег</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#102a3b;--muted:#587080;--blue:#dcecf4;--ice:#f3f8fa;--orange:#fa6b42;--line:#d6e3e9;--navy:#12374b}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--ice);color:var(--ink);font-family:Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,a{-webkit-tap-highlight-color:transparent}.wrap{width:min(1180px,calc(100% - 48px));margin-inline:auto}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:11px;font-weight:800;letter-spacing:.02em}.brand-mark{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:var(--orange);color:#fff;font-size:20px}.brand span:last-child{font-size:16px}.nav{display:flex;gap:31px;color:#526a79;font-size:14px;font-weight:700}.nav a:hover{color:var(--orange)}.top-action{font-size:14px;font-weight:800;padding:13px 19px;border:1px solid #a9c0cd;border-radius:30px;transition:.2s}.top-action:hover{background:var(--navy);color:white;border-color:var(--navy)}.hero{width:100%;min-height:645px;position:relative;overflow:hidden;border-radius:0;background:#b9d5e5 url('/images/snowkiting/hero.png') center 47%/cover no-repeat;color:white;display:flex;align-items:center}.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(7,28,44,.74) 0%,rgba(7,28,44,.45) 41%,rgba(7,28,44,.04) 80%),linear-gradient(0deg,rgba(10,38,54,.30),transparent 45%)}.hero-content{position:relative;z-index:1;width:min(620px,65%);padding:68px 0 76px max(calc((100% - 1180px)/2 + 100px), 8.5%)}.eyebrow{display:flex;align-items:center;gap:10px;text-transform:uppercase;font-size:14px;letter-spacing:.2em;font-weight:800;color:#d4ebf5}.eyebrow:before{content:"";height:2px;width:26px;background:var(--orange)}h1,h2,h3,p{margin-top:0}.hero h1{font-family:Oswald,Impact,sans-serif;font-size:clamp(58px,8vw,104px);font-weight:600;letter-spacing:-.025em;line-height:.98;text-transform:uppercase;margin:25px 0 22px;max-width:700px}.hero h1 em{color:#ff805c;font-style:normal}.hero-copy{max-width:440px;color:#e5f2f8;font-size:16px;line-height:1.75;margin-bottom:30px}.button{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:52px;padding:0 23px;border-radius:3px;background:var(--orange);color:white;font-size:14px;font-weight:800;letter-spacing:.02em;transition:transform .2s,background .2s}.button:after{content:"↗";font-size:17px}.button:hover{background:#e85d36;transform:translateY(-2px)}.hero-note{display:flex;align-items:center;gap:10px;margin-top:23px;font-size:14px;color:#d3e4ec}.hero-note b{width:7px;height:7px;border-radius:50%;background:#83d6bd}.hero-index{position:absolute;right:34px;bottom:30px;writing-mode:vertical-rl;font-size:14px;letter-spacing:.18em;color:#e3eef3}.intro{padding:107px 0 102px;display:grid;grid-template-columns:.95fr 1.05fr;gap:90px;align-items:start}.section-label{font-size:14px;text-transform:uppercase;letter-spacing:.2em;color:#7791a1;font-weight:800;margin-bottom:20px}.intro h2,.section-heading{font-family:Oswald,Impact,sans-serif;text-transform:uppercase;font-size:clamp(39px,5vw,61px);line-height:1.02;letter-spacing:-.015em;font-weight:600;margin-bottom:0}.intro h2 span{color:#7898a9}.intro-copy{font-size:15px;color:var(--muted);line-height:1.9;padding-top:22px}.intro-copy strong{color:var(--ink)}.stats{display:flex;gap:40px;border-top:1px solid var(--line);padding-top:24px;margin-top:32px}.stat strong{display:block;font-family:Oswald,sans-serif;font-size:26px;color:var(--orange);margin-bottom:4px}.stat span{font-size:14px;color:#718796;line-height:1.4}.dark-section{background:var(--navy);color:white;padding:94px 0 100px}.section-top{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:48px}.dark-section .section-label{color:#83a5b6}.dark-section .section-heading{max-width:620px}.section-note{max-width:260px;font-size:14px;line-height:1.8;color:#b5cbd5}.steps{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #416174}.step{padding:26px 34px 0 0;position:relative}.step+.step{border-left:1px solid #416174;padding-left:30px}.step-no{font-family:Oswald,sans-serif;font-size:14px;color:#ff805c;letter-spacing:.08em}.step h3{font-size:19px;margin:23px 0 11px}.step p{font-size:14px;line-height:1.85;color:#bed0d9;max-width:300px;margin:0}.step-icon{display:grid;place-items:center;width:43px;height:43px;border:1px solid #5c7b8d;border-radius:50%;margin-top:28px;color:#a8d1e3;font-size:20px}.promise{padding:100px 0;display:grid;grid-template-columns:1.1fr .9fr;gap:85px;align-items:center}.promise h2{font-family:Oswald,sans-serif;text-transform:uppercase;font-size:clamp(40px,5vw,62px);line-height:1.03;margin:0 0 23px}.promise-copy{font-size:14px;line-height:1.9;color:var(--muted);max-width:500px}.promise-list{list-style:none;margin:30px 0 0;padding:0;display:grid;gap:17px}.promise-list li{display:flex;gap:13px;font-size:14px;line-height:1.6}.promise-list li:before{content:"↗";color:var(--orange);font-weight:800}.quote-card{background:#e3eef3;padding:36px 36px 32px;position:relative;min-height:292px;display:flex;flex-direction:column;justify-content:space-between}.quote-card:before{content:"";position:absolute;top:0;left:0;width:5px;height:100%;background:var(--orange)}.quote-card blockquote{font-family:Oswald,sans-serif;font-size:30px;line-height:1.24;text-transform:uppercase;margin:0;max-width:360px}.quote-card p{font-size:14px;color:#6a8291;margin:29px 0 0}@keyframes snow-ice-shimmer{0%{background-position:0% 48%}100%{background-position:100% 52%}}@keyframes snow-cloud-drift{0%{transform:translate3d(-1.5%,0,0)}100%{transform:translate3d(1.5%,1%,0)}}@keyframes snow-wind{0%{transform:translate3d(-2%,0,0)}100%{transform:translate3d(2%,0,0)}}.conditions{position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(115deg,#d9edf6 0%,#edf7fb 35%,#cfe7f3 65%,#e9f5fa 100%);background-size:240% 240%;animation:snow-ice-shimmer 18s ease-in-out infinite alternate;padding:86px 0}.conditions:before{content:"";position:absolute;inset:-12%;z-index:0;pointer-events:none;opacity:.8;filter:blur(12px);background:radial-gradient(ellipse 250px 88px at 80% 24%,rgba(255,255,255,.82) 0 48%,transparent 76%),radial-gradient(ellipse 190px 70px at 68% 27%,rgba(255,255,255,.74) 0 48%,transparent 76%),radial-gradient(ellipse 210px 74px at 92% 29%,rgba(255,255,255,.75) 0 48%,transparent 76%),radial-gradient(ellipse 280px 90px at 16% 86%,rgba(255,255,255,.48) 0 48%,transparent 76%);animation:snow-cloud-drift 25s ease-in-out infinite alternate}.conditions:after{content:"";position:absolute;inset:-25%;z-index:0;pointer-events:none;opacity:.4;background:repeating-linear-gradient(168deg,transparent 0 96px,rgba(255,255,255,.66) 98px,transparent 101px 144px);mask-image:linear-gradient(90deg,transparent,#000 14%,#000 86%,transparent);animation:snow-wind 16s ease-in-out infinite alternate}.conditions-inner{position:relative;z-index:1;display:grid;grid-template-columns:.85fr 1.15fr;gap:70px}.conditions h2{font-family:Oswald,sans-serif;text-transform:uppercase;font-size:48px;line-height:1.02;margin:0}.conditions-desc{font-size:14px;color:var(--muted);line-height:1.8;margin-top:18px;max-width:370px}.condition-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px 36px}.condition{border-top:1px solid #bdd0da;padding-top:14px}.condition strong{font-size:14px;display:block;margin-bottom:7px}.condition span{font-size:14px;color:#647d8c;line-height:1.6;display:block}.closing{position:relative;isolation:isolate;overflow:hidden;padding:0;text-align:left;background:#dcecf4}.closing-background{position:absolute;inset:0;z-index:-1;width:100%;height:100%;object-fit:cover;object-position:center 58%}.closing-inner{position:relative;display:grid;grid-template-columns:1fr 1fr;min-height:600px;align-items:center}.closing-content{width:min(100%,560px);margin-left:auto;padding:42px;background:rgba(246,250,251,.88);border:1px solid rgba(255,255,255,.82);box-shadow:0 18px 55px rgba(16,42,59,.12);backdrop-filter:blur(8px);text-align:left}.closing .section-label{margin-bottom:18px}.closing h2{font-family:Oswald,sans-serif;font-size:clamp(48px,7vw,82px);text-transform:uppercase;line-height:.98;max-width:800px;margin:0 0 22px}.closing p{color:var(--muted);font-size:14px;line-height:1.8;max-width:490px;margin:0 0 28px}.closing-content .contact-number{margin:20px 0 0!important}.footer{background:var(--navy);color:white;padding:25px 0}.footer-inner{display:flex;justify-content:space-between;align-items:center;gap:24px}.footer small{font-size:14px;color:#a9c1cc}.footer .brand-mark{width:30px;height:30px;font-size:16px}.footer .brand span:last-child{font-size:14px}
        .contact-number{margin:20px auto 0!important;font-size:14px!important}.contact-number a{font-weight:800;color:var(--navy);text-decoration:underline;text-decoration-color:var(--orange);text-underline-offset:4px}.phone-label{font-weight:700;color:#d9e8ef}.closing .phone-label{color:var(--navy)}
        .dev-notice{position:fixed;z-index:4;right:0;top:50%;transform:translateY(-50%);display:flex;align-items:flex-start;justify-content:space-between;gap:20px;width:min(540px,calc(100vw - 24px));min-height:190px;padding:38px 28px 38px 38px;background:linear-gradient(115deg,#30271e,#72502e,#493328,#30271e);background-size:300% 300%;animation:snow-dev-gradient 12s ease-in-out infinite alternate;color:#f4f0e5;box-shadow:0 8px 32px #21180f50;font-size:clamp(22px,3.2vw,38px);line-height:1.3}.dev-notice a{color:#ffdc9c;font-weight:700;text-decoration:underline;text-underline-offset:5px}.dev-notice button{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;margin:-12px -12px 0 0;border:0;background:transparent;color:#f4f0e5;font-size:36px;line-height:1}.dev-notice button:hover{color:var(--orange)}.dev-notice-offer{font-size:clamp(16px,1.6vw,20px);line-height:1.5;margin:18px 0 0}.dev-notice-offer strong{white-space:nowrap}@keyframes snow-dev-gradient{from{background-position:0% 50%}to{background-position:100% 50%}}@media(max-width:760px){.dev-notice{min-height:150px;padding:30px 22px 30px 24px;gap:12px}.dev-notice button{margin:-10px -10px 0 0}}
        @media(max-width:800px){.wrap{width:min(100% - 34px,620px)}.topbar{height:70px}.nav{display:none}.top-action{font-size:14px;padding:11px 13px}.hero{min-height:620px;background-position:60% center}.hero:before{background:linear-gradient(90deg,rgba(7,28,44,.72),rgba(7,28,44,.2)),linear-gradient(0deg,rgba(10,38,54,.38),transparent 65%)}.hero-content{width:90%;padding:60px 0 70px 8%}.hero h1{font-size:clamp(58px,14vw,88px)}.hero-copy{font-size:14px;max-width:360px}.intro{padding:72px 0;grid-template-columns:1fr;gap:20px}.intro-copy{padding-top:0}.stats{gap:25px}.section-top{display:block;margin-bottom:35px}.section-note{margin-top:18px}.dark-section{padding:72px 0}.steps{grid-template-columns:1fr;border-top:0;gap:0}.step,.step+.step{border-top:1px solid #416174;border-left:0;padding:20px 0 25px}.step h3{margin-top:15px}.step-icon{display:none}.promise{padding:72px 0;grid-template-columns:1fr;gap:32px}.quote-card{min-height:230px}.conditions{padding:70px 0}.conditions-inner{grid-template-columns:1fr;gap:34px}.closing{padding:0;text-align:left}.closing-inner{grid-template-columns:1fr;min-height:0;padding:310px 0 26px}.closing-spacer{display:none}.closing-background{object-position:24% center}.closing-content{width:100%;padding:30px}.footer-inner{align-items:flex-start;flex-direction:column;gap:15px}}
        @media(max-width:440px){.wrap{width:calc(100% - 28px)}.brand span:last-child{font-size:14px}.top-action{padding:10px 11px}.hero{min-height:585px}.hero-content{padding-left:6%;width:95%}.hero h1{font-size:56px}.hero-copy{max-width:310px}.hero-index{right:15px;bottom:16px}.intro h2,.section-heading{font-size:42px}.stats{gap:18px}.stat strong{font-size:22px}.stat span{font-size:14px}.condition-grid{grid-template-columns:1fr;gap:17px}.quote-card{padding:28px}.quote-card blockquote{font-size:26px}}
        @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important}.conditions{animation:none}.conditions:before,.conditions:after{animation:none}.dev-notice{animation:none}}
    
        .dev-notice-full{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;width:100%}.dev-notice-full>div{flex:1}.dev-notice-compact{display:flex;align-items:center;justify-content:space-between;gap:14px;width:100%;font-size:14px}.dev-notice-compact[hidden],.dev-notice-full[hidden]{display:none!important}.dev-notice-compact strong{font-size:15px;white-space:nowrap}.dev-notice-compact button{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;margin:0;border:1px solid currentColor;border-radius:50%;background:transparent;color:inherit;font-size:25px;line-height:1}.dev-notice.is-collapsed{width:min(340px,calc(100vw - 24px));min-height:0;padding:12px 14px 12px 18px;align-items:center}.dev-notice.is-collapsed .dev-notice-full{display:none}
    </style>
</head>
<body>
    {{ $slot }}
</body>
</html>
